<template><main class="container page-section"><p class="eyebrow">Explore</p><h1 class="page-title">发现公开文章</h1><form class="filters" @submit.prevent="load"><input v-model="q" aria-label="搜索文章" placeholder="搜索标题或摘要"><select v-model="sort" aria-label="排序"><option value="latest">最新</option><option value="hot">热门</option></select><button class="button button-primary">搜索</button></form><div class="taxonomy"><button v-for="category in taxonomy.categories" :key="category.slug" :class="{selected:category.slug===selectedCategory}" @click="selectedCategory=category.slug;load()">{{category.name}}</button></div><div v-if="loading" class="empty">加载中…</div><div v-else-if="!items.length" class="empty">没有匹配的公开文章。</div><div v-else class="feed"><article v-for="post in items" :key="post.id" class="card item"><div><p class="post-meta">{{post.username}} · {{date(post.published_at)}} · {{post.reading_minutes}} 分钟</p><h2><RouterLink :to="`/posts/${post.slug}`">{{post.title}}</RouterLink></h2><p class="muted">{{post.excerpt||post.content_markdown.slice(0,160)}}</p></div><div class="counts">{{post.view_count}} 阅读　{{post.like_count}} 喜欢</div></article></div></main></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{RouterLink}from'vue-router';import http from '@/services/http';const q=ref(''),sort=ref('latest'),selectedCategory=ref(''),items=ref<any[]>([]),loading=ref(true),taxonomy=ref<any>({categories:[]});const date=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v));async function load(){loading.value=true;try{items.value=(await http.get('/api/public/posts',{params:{q:q.value,sort:sort.value,category:selectedCategory.value||undefined}})).data.items}finally{loading.value=false}}onMounted(async()=>{try{taxonomy.value=(await http.get('/api/public/taxonomy')).data}catch{};load()})</script>
<style scoped>.filters{display:flex;gap:8px;margin:24px 0}.filters input,.filters select{min-height:40px;border:1px solid var(--border);background:var(--surface);color:var(--text);border-radius:8px;padding:0 10px}.filters input{flex:1}.taxonomy{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:24px}.taxonomy button{background:transparent;border:0;color:var(--muted);padding:6px 8px}.taxonomy .selected,.taxonomy button:hover{color:var(--accent);background:var(--accent-soft);border-radius:6px}.feed{display:grid;gap:12px}.item{padding:20px;display:flex;justify-content:space-between;gap:24px}.item h2{font-size:1.25rem;margin:5px 0}.item h2 a{text-decoration:none}.counts,.post-meta{font-size:.82rem;color:var(--subtle);white-space:nowrap}@media(max-width:640px){.filters{flex-wrap:wrap}.filters input{min-width:100%}.item{display:block}.counts{margin-top:12px}}</style>
